<template><q-page class="page"><p class="eyebrow">ADMINISTRAÇÃO</p><h1 class="page-title">Revisar questões</h1><p class="copy">Revise classificação e envie várias questões para aprovação de uma vez.</p><q-banner v-if="error" rounded class="error">{{error}}</q-banner><q-inner-loading :showing="loading" color="primary"/><div v-if="questions.length" class="batch"><q-checkbox v-model="allSelected" label="Selecionar todas as questões em revisão"/><q-btn unelevated no-caps color="primary" icon="fact_check" :disable="!selectedIds.length" :loading="marking" :label="'Marcar para aprovação (' + selectedIds.length + ')'" @click="markSelected"/></div><q-list v-if="questions.length" bordered separator class="list"><q-expansion-item v-for="question in questions" :key="question.id"><template #header><q-item-section avatar><q-checkbox v-if="question.status==='REVIEW'" :model-value="selectedIds.includes(question.id)" @update:model-value="toggle(question.id, $event)" @click.stop/></q-item-section><q-item-section><q-item-label lines="2">{{question.statement}}</q-item-label><q-item-label caption>{{question.status==='REVIEW' ? 'Em revisão' : 'Aguardando aprovação'}} · {{question.board ?? 'Banca não identificada'}}</q-item-label></q-item-section></template><q-card flat><q-card-section><div class="question-header"><strong>{{ question.board ?? 'Banca não identificada' }}</strong><span>{{ contestLine(question) }}</span><span>{{ positionLine(question) }}</span></div><div class="statement"><p v-for="part in statementParts(question.statement)" :key="part">{{part}}</p></div><p v-for="option in question.options" :key="option.id"><strong>{{option.label}}.</strong> {{option.content}}</p><q-select :options="subjectOptions" multiple emit-value map-options option-label="label" option-value="value" outlined label="Assuntos canônicos" v-model="selected[question.id]"/><div class="actions"><q-btn v-if="question.status==='DRAFT'" unelevated no-caps color="primary" label="Publicar questão" :loading="publishing===question.id" @click="publish(question.id)"/><q-btn flat no-caps color="primary" label="Salvar assuntos" :loading="savingTaxonomy===question.id" @click="assignTaxonomy(question.id,selected[question.id]??[])"/></div></q-card-section></q-card></q-expansion-item></q-list><q-card v-else-if="!loading" flat class="empty"><q-card-section>Nenhuma questão pendente de revisão.</q-card-section></q-card></q-page></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import type{PublishedQuestion}from'../../../Domain/QuestionBank/QuestionRepository';import{useEditorial}from'./useEditorial';const{assignTaxonomy,error,load,loading,markForApproval,marking,publishing,publish,questions,savingTaxonomy,subjects}=useEditorial();const selected=reactive<Record<string,string[]>>({});const selectedIds=ref<string[]>([]);const subjectOptions=computed(()=>subjects.value.map(s=>({label:'· '.repeat(s.level)+s.name,value:s.id})));const reviewIds=computed(()=>questions.value.filter(q=>q.status==='REVIEW').map(q=>q.id));const allSelected=computed({get:()=>reviewIds.value.length>0&&reviewIds.value.every(id=>selectedIds.value.includes(id)),set:(value:boolean)=>{selectedIds.value=value?[...reviewIds.value]:[]}});watch(questions,(items)=>{for(const question of items)selected[question.id]=[...(question.taxonomySubjectIds??[])];selectedIds.value=selectedIds.value.filter(id=>items.some(question=>question.id===id&&question.status==='REVIEW'))},{immediate:true});function contestLine(question:PublishedQuestion):string{const p=(question.source??'').split('/').filter(Boolean);return (p.slice(0,2).join(' · ')||'Concurso não identificado')+(question.year?' · '+question.year:'')}function positionLine(question:PublishedQuestion):string{const p=(question.source??'').split('/').filter(Boolean);return p.slice(2).join(' · ')||'Cargo não identificado'}function statementParts(value:string):string[]{const normalized=value.replace(/\s+/g,' ').trim();const match=normalized.match(/^(.*?afirmativas? a seguir\.?)(.*)$/i);if(!match)return[normalized];const assertions=match[2].split(/(?=\s(?:I|II|III|IV|V|VI|VII|VIII|IX|X)\.)/).map(item=>item.trim()).filter(Boolean);return [match[1].trim(),...assertions]}function toggle(id:string,value:boolean){selectedIds.value=value?[...new Set([...selectedIds.value,id])]:selectedIds.value.filter(item=>item!==id)}async function markSelected(){await markForApproval(selectedIds.value);selectedIds.value=[]}onMounted(load);</script>
<style scoped>.page{max-width:1000px;margin:auto;padding:42px 34px}.eyebrow{color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.page h1{color:#142950;margin:0}.copy{color:#71819e}.list,.empty,.batch{background:#fff;border:1px solid #e5ecf6;border-radius:16px;overflow:hidden}.batch{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 16px;margin-bottom:16px}.error{margin:16px 0;background:#fff3f2;color:#ae2f25}.question-header{display:grid;gap:2px;padding:12px 14px;background:#eaf2ff;border-left:3px solid #1469e8;border-radius:10px;color:#153a78}.question-header strong{font-size:14px}.question-header span{font-size:12px}.statement{margin:16px 0}.statement p{white-space:pre-line}.q-card p{padding:8px;background:#f6f8fc;border-radius:8px}.actions{display:flex;gap:8px;margin-top:12px}@media(max-width:600px){.page{padding:28px 16px}.batch{align-items:stretch;flex-direction:column}}</style>